public final class Session implements AutoCloseable {
    private final AtomicBoolean closed = new AtomicBoolean();
    private final FileChannel channel = FileChannel.open(Path.of("session.bin"));

    @Override public void close() throws IOException {
        if (closed.compareAndSet(false, true)) channel.close();  // idempotent cascade
    }
}

try (Session s = new Session()) {
    use(s);                          // close() on normal exit and on exceptions
}

