public final class NativeBuffer implements AutoCloseable {
    private static final Cleaner CLEANER = Cleaner.create();
    private static final class State implements Runnable {   // no outer reference
        private long addr;
        State(long addr) { this.addr = addr; }
        public void run() { if (addr != 0) { free(addr); addr = 0; } }
    }

    private final State state = new State(malloc(4096));
    private final Cleaner.Cleanable cleanable = CLEANER.register(this, state);
    @Override public void close() { cleanable.clean(); }     // idempotent release
}
